        print(f"== INTEGRATION trace={r.get('trace_id')}")
        for c in r['checks']: print(f"   {c['result']:8} {c['check'][:90]} | {c['evidence'][:220].replace(chr(10),' ')}")
        print('   inconsistencies:'); [print('     -',x[:400]) for x in r.get('cross_area_inconsistencies',[])]
        print('   JUDGMENT:', r.get('judgment')[:800])
    elif 'closed' in r:
        print(f"== FIX {r.get('area')} trace={r.get('trace_id')} closed={r['closed']}")
        for p in r['partial']: print(f"   partial {p['id']}: {p['reason'][:250]}")
        for p in r['not_closed']: print(f"   NOT {p['id']}: {p['reason'][:250]}")
        print('   files:', [f.split('vcr-build/')[-1] for f in r['files_changed']])
        for q in r.get('open_questions',[]): print('   Q:', q[:300])
